-- ═════════════════════════════════════════════════════════════════════════════
-- PLAN INDICATIVO PDI 2022–2031 (Versión 2): 134 indicadores de resultado con su línea base, metas por trienio y meta PDI.
-- Origen: pestaña "Plan Indicativo PDI" de Historico_indicadores_Plan_de_Accion_2022-2026.xlsx
--
-- Cómo usarlo: ejecuta TODO el archivo. Se puede repetir: reemplaza el contenido de la tabla plan_indicativo_144.
-- Los porcentajes se guardan como fracción (0.39 = 39 %) y se marcan con es_porcentaje = 1.
-- ═════════════════════════════════════════════════════════════════════════════
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS plan_indicativo_144 (
    id INT AUTO_INCREMENT PRIMARY KEY, numero INT NOT NULL, linea VARCHAR(255) NOT NULL, motor VARCHAR(255) NOT NULL, proyecto VARCHAR(500) NOT NULL,
    meta_resultado TEXT NULL, indicador TEXT NOT NULL, formula TEXT NULL,
    linea_base DECIMAL(18,4) NULL, t2022_2024 DECIMAL(18,4) NULL, t2025_2027 DECIMAL(18,4) NULL, t2028_2030 DECIMAL(18,4) NULL, a2031 DECIMAL(18,4) NULL,
    meta_pdi DECIMAL(18,4) NULL, es_porcentaje TINYINT NOT NULL DEFAULT 0, pagina_pdf INT NULL, KEY idx_numero (numero)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

START TRANSACTION;
DELETE FROM plan_indicativo_144;
COMMIT;

-- Verificación (debe dar 134):
SELECT COUNT(*) AS indicadores FROM plan_indicativo_144;
